// 📊 COLLECTEUR ROBUSTE - Basé sur la doc n8n v4
const webhookData = $input.item.json.body;
const binaryData = $input.item.binary;

console.log('📊 COLLECTEUR ROBUSTE:');
console.log('- Body keys:', Object.keys($input.item.json));
console.log('- Contenu présent:', !!webhookData?.contenu);
console.log('- Binary présent:', !!binaryData);
console.log('- Binary keys:', binaryData ? Object.keys(binaryData) : 'none');

// Debug détaillé des binaires
if (binaryData) {
  Object.entries(binaryData).forEach(([key, value]) => {
    console.log(`📎 Binary [${key}]:`, {
      type: typeof value,
      hasData: !!(value?.data),
      hasBuffer: !!(value?.buffer),
      hasId: !!(value?.id),
      mimeType: value?.mimeType,
      fileName: value?.fileName,
      keys: Object.keys(value || {})
    });
  });
}

if (!webhookData?.contenu) {
  throw new Error('Contenu manquant dans body');
}

// Normalisation binary selon patterns n8n
const normalizedBinary = {};
if (binaryData && Object.keys(binaryData).length > 0) {
  // Prendre la première entrée binary et la standardiser
  const [firstKey, firstValue] = Object.entries(binaryData)[0];
  console.log('📎 Normalisation:', firstKey, '→ images');

  // Vérifier que c'est une vraie donnée binary
  if (firstValue && (firstValue.data || firstValue.buffer || firstValue.id)) {
    normalizedBinary.images = {
      data: firstValue.data || firstValue.buffer,
      mimeType: firstValue.mimeType || 'image/png',
      fileName: firstValue.fileName || 'image.png',
      directory: firstValue.directory,
      id: firstValue.id
    };
    console.log('✅ Binary normalisé pour Flask');
  } else {
    console.log('❌ Données binary invalides');
  }
}

return {
  json: {
    contenu_pour_openai: webhookData.contenu,
    contenu_original: webhookData.contenu,
    subtitle_original: webhookData.subtitle || '',
    binary_debug: {
      original_keys: binaryData ? Object.keys(binaryData) : [],
      normalized_keys: Object.keys(normalizedBinary),
      has_valid_binary: Object.keys(normalizedBinary).length > 0
    }
  },
  binary: normalizedBinary
};

// 🔗 FUSION ULTIME - Pattern doc n8n v4 pour binary
const openAIResult = $input.item;
const collectorData = $node["📊 Collecteur"];

console.log('🔗 FUSION ULTIME:');
console.log('- OpenAI présent:', !!openAIResult);
console.log('- Collecteur présent:', !!collectorData);

// Parse IA (structure confirmée)
let aiTitle = 'Titre par défaut';
let aiSubtitle = 'Sous-titre par défaut';
let aiBody = 'Corps par défaut';

const aiResponse = openAIResult.json?.message?.content;
if (aiResponse) {
  console.log('🤖 AI Response:', aiResponse.substring(0, 100));
  try {
    const cleanResponse = aiResponse.replace(/```json\n?|```\n?/g, '').trim();
    const analysis = JSON.parse(cleanResponse);

    aiTitle = analysis.title || aiTitle;
    aiSubtitle = analysis.subtitle || aiSubtitle;
    aiBody = analysis.body || aiBody;

    console.log('✅ IA PARSED - Title:', aiTitle);
  } catch (e) {
    console.log('❌ IA PARSE ERROR:', e.message);
  }
} else {
  console.log('❌ Pas de contenu IA');
}

// Binary handling robuste selon doc n8n
const collectorBinary = collectorData?.binary || {};
const finalBinary = {};

console.log('📎 BINARY PROCESSING:');
console.log('- Collector binary keys:', Object.keys(collectorBinary));

if (collectorBinary.images) {
  const imageData = collectorBinary.images;
  console.log('📎 Image data structure:', {
    hasData: !!(imageData.data),
    hasBuffer: !!(imageData.buffer),
    hasId: !!(imageData.id),
    mimeType: imageData.mimeType,
    fileName: imageData.fileName
  });

  // Créer binary conforme n8n pour HTTP Request
  if (imageData.data || imageData.buffer || imageData.id) {
    finalBinary.images = {
      data: imageData.data || imageData.buffer,
      mimeType: imageData.mimeType || 'image/png',
      fileName: imageData.fileName || 'image.png'
    };

    // Si c'est un ID, garder la référence
    if (imageData.id) {
      finalBinary.images.id = imageData.id;
    }

    console.log('✅ Binary final prêt pour HTTP Request');
  } else {
    console.log('❌ Données binary incomplètes');
  }
} else {
  console.log('⚠️ Pas de binary images du collecteur');
}

return {
  json: {
    ai_title: aiTitle,
    ai_subtitle: aiSubtitle,
    ai_body: aiBody,

    debug: {
      ai_parsing_success: aiTitle !== 'Titre par défaut',
      binary_available: Object.keys(finalBinary).length > 0,
      binary_structure: Object.keys(finalBinary),
      collector_binary_debug: collectorData?.json?.binary_debug
    }
  },
  binary: finalBinary
};

const flaskResponse = $input.item.json;
const fusionData = $input.first();

if (flaskResponse?.success) {
  return {
    json: {
      status: 'success',
      message: '🎉 Document créé avec IA !',
      project_id: flaskResponse.project_id,
      download_url: `http://host.docker.internal:5003/api/download/${flaskResponse.project_id}`,

      ai_content: {
        title: fusionData?.json?.ai_title,
        subtitle: fusionData?.json?.ai_subtitle,
        body_preview: fusionData?.json?.ai_body?.substring(0, 100) + '...'
      },

      technical: {
        ai_parsing_success: fusionData?.json?.debug?.ai_parsing_success,
        binary_processed: fusionData?.json?.debug?.binary_available,
        route_used: fusionData?.json?.debug?.binary_available ? 'with_binary' : 'text_only'
      }
    }
  };
}

return {
  json: {
    status: 'error',
    error: flaskResponse?.error || 'Erreur Flask',
    debug: { flask_response: flaskResponse, fusion_debug: fusionData?.json?.debug }
  }
};
